<map version="1.0.1"><node CREATED="1747229423432" ID="ID_root" MODIFIED="1747229423432" TEXT="无缓冲文件流"><node CREATED="1747229423432" ID="ID_e2fce7d27c98bc7d" POSITION="right" MODIFIED="1747229423432" TEXT="概述"><node CREATED="1747229423432" ID="ID_9a7a6790e60a2aef" MODIFIED="1747229423432" TEXT="有缓冲文件流"><node CREATED="1747229423432" ID="ID_1ebf445b4814b1ee" MODIFIED="1747229423432" TEXT="之前使用的fopen就是这个类型的文件流。它是有一个缓冲区的（就是一块内存，这块内存在用户空间）。&amp;lt;br&amp;gt;"></node><node CREATED="1747229423432" ID="ID_c9dbd95ace9d3488" MODIFIED="1747229423432" TEXT="凡是需要涉及读磁盘，都需要经过内核。这时候就有一个&amp;nbsp;从&amp;nbsp;用户态到内核态的转换。这个转换非常耗费性能。&amp;lt;br&amp;gt;所以我们想尽可能减少这种状态转换"></node></node><node CREATED="1747229423432" ID="ID_cce78de4bdbc2f83" MODIFIED="1747229423432" TEXT="无缓冲文件流"><node CREATED="1747229423432" ID="ID_a33eaa506b89a179" MODIFIED="1747229423432" TEXT="在用户空间，没有缓冲区。&amp;nbsp;我们每一次读的数据，都是从内核态取出来的"></node><node CREATED="1747229423432" ID="ID_a89c2ae5b75e3e3c" MODIFIED="1747229423432" TEXT="返回值的变化，&amp;nbsp;有缓冲区文件流返回的是FILE *。这个结构体里面有地址，这个地址是用户空间的。&amp;lt;br&amp;gt;现在，没有缓冲区之后。返回的是一个int，叫做文件描述符。&amp;nbsp;用来给内核描述，我需要取什么数据回来。&amp;lt;br&amp;gt;文件描述符的详细信息，内核是知道的（）。但是我们（用户空间）不知道。"></node></node><node CREATED="1747229423432" ID="ID_12eeaae39c3c2b00" MODIFIED="1747229423432" TEXT="流程也非常重要，数据是怎么流的，这个才是重点"></node></node><node CREATED="1747229423432" ID="ID_7c646de7e8f55255" POSITION="right" MODIFIED="1747229423432" TEXT="使用"><node CREATED="1747229423432" ID="ID_13842575c42aa042" MODIFIED="1747229423432" TEXT="打开流"><node CREATED="1747229423432" ID="ID_fa7a5532e8fdde10" MODIFIED="1747229423432" TEXT="open"><node CREATED="1747229423432" ID="ID_c23046353b7a461a" MODIFIED="1747229423432" TEXT="int open(const char *pathname, int flags);&amp;lt;br&amp;gt;int open(const char *pathname, int flags, mode_t mode);"></node><node CREATED="1747229423432" ID="ID_bf0f27353e6ce004" MODIFIED="1747229423432" TEXT="flags：&amp;nbsp;打开的模式。"><node CREATED="1747229423432" ID="ID_d611c3ff3c86fd03" MODIFIED="1747229423432" TEXT="使用宏定义来表示含义。宏定义其实是使用的特定的某一位来标识含义。&amp;lt;br&amp;gt;大家使用这些宏定义组合的时候，使用 |"></node><node CREATED="1747229423432" ID="ID_c57c378e4d72313d" MODIFIED="1747229423432" TEXT="O_RDONLY"></node><node CREATED="1747229423432" ID="ID_2461f01cc7c7a65a" MODIFIED="1747229423432" TEXT="O_WRONLY"></node><node CREATED="1747229423432" ID="ID_031f2f7044695244" MODIFIED="1747229423432" TEXT="O_RDWR"></node><node CREATED="1747229423432" ID="ID_39899cd0fa341aa9" MODIFIED="1747229423432" TEXT="O_CREAT"></node><node CREATED="1747229423432" ID="ID_97e038cee2110713" MODIFIED="1747229423432" TEXT="O_TRUNC"></node><node CREATED="1747229423432" ID="ID_749339a3c6ad4d3f" MODIFIED="1747229423432" TEXT="O_APPEND"></node><node CREATED="1747229423432" ID="ID_7d16e01444ac0bdf" MODIFIED="1747229423432" TEXT="O_EXCL"><node CREATED="1747229423432" ID="ID_5ac45423ee307b53" MODIFIED="1747229423432" TEXT="这个就是独占。文件不存在，创建。文件存在报错。&amp;nbsp;"></node></node><node CREATED="1747229423432" ID="ID_5b7855547c0e9c0e" MODIFIED="1747229423432" TEXT="把一些重点的记一下"><node CREATED="1747229423432" ID="ID_9c57f0bbcdaf7e43" MODIFIED="1747229423432" TEXT="r: O_RDONLY"></node><node CREATED="1747229423432" ID="ID_c373dd75c65b31f1" MODIFIED="1747229423432" TEXT="w: O_WRONLY | O_CREAT | O_TRUNC&amp;lt;br&amp;gt;如果要创建，一定要记得加权限。&amp;nbsp;"></node></node></node></node></node><node CREATED="1747229423432" ID="ID_e59b0a91afa7bd86" MODIFIED="1747229423432" TEXT="使用流"><node CREATED="1747229423432" ID="ID_f9e26442e07f6ccc" MODIFIED="1747229423432" TEXT="read"><node CREATED="1747229423432" ID="ID_7c5985acd30f6854" MODIFIED="1747229423432" TEXT="读数据。"></node></node><node CREATED="1747229423432" ID="ID_8ae28860749bd67b" MODIFIED="1747229423432" TEXT="write"><node CREATED="1747229423432" ID="ID_4932ccedc9d85769" MODIFIED="1747229423432" TEXT="写数据"></node></node></node><node CREATED="1747229423432" ID="ID_ea20dcba599e4f48" MODIFIED="1747229423432" TEXT="关闭流"><node CREATED="1747229423432" ID="ID_34e9a66039a65537" MODIFIED="1747229423432" TEXT="close&amp;nbsp;"></node></node><node CREATED="1747229423432" ID="ID_841cfeb0088ffc9f" MODIFIED="1747229423432" TEXT="文本复制的时候"><node CREATED="1747229423432" ID="ID_db59bb00df2892ea" MODIFIED="1747229423432" TEXT="可以使用计时器获取当前的ms。&amp;nbsp;然后对比一下，数组的大小，对于文本复制的速度是否有影响"></node><node CREATED="1747229423432" ID="ID_af37ba5bdf63d22d" MODIFIED="1747229423432" TEXT="100&amp;nbsp;速度就会比较慢。&amp;nbsp;但是1000 2000 4000&amp;nbsp;"></node><node CREATED="1747229423432" ID="ID_6a54e24aafa76de0" MODIFIED="1747229423432" TEXT="数组的大小，不要太小。&amp;nbsp;建议大小 4096&amp;nbsp; 8192。"></node></node></node><node CREATED="1747229423432" ID="ID_dfcf89c99cda3521" POSITION="right" MODIFIED="1747229423432" TEXT="特殊的函数"><node CREATED="1747229423432" ID="ID_fbb1c4c48e765627" MODIFIED="1747229423432" TEXT="ftruncate&amp;nbsp;"><node CREATED="1747229423432" ID="ID_0b56b9fdf15dbecc" MODIFIED="1747229423432" TEXT="用于改变一个已经打开的文件的大小。&amp;nbsp;比如可以让它大点。让它小点"></node><node CREATED="1747229423432" ID="ID_d18c19a2d15c388e" MODIFIED="1747229423432" TEXT="有啥用：&amp;nbsp;主要用于占位。&amp;nbsp;在一些下载的场景中，我们会事先用 ftruncate&amp;nbsp;占指定大小。&amp;nbsp;用来保证&amp;lt;br&amp;gt;先把磁盘空间占上，不会下载到一半，才发现，空间不足"></node><node CREATED="1747229423432" ID="ID_dbd7b938d97bf84f" MODIFIED="1747229423432" TEXT="fd一定要有w权限。&amp;nbsp;如果没有w权限，没得玩"></node></node></node></node></map>